mapper.update:
UPDATE sol_construction_plan_revision
SET calculation_basis_code = #{update.calculationBasisCode},
    start_date = #{update.startDate},
    end_date = #{update.endDate},
    duration_days = #{update.durationDays},
    source_change_id = #{update.sourceChangeId},
    version = version + 1
WHERE tenant_id = #{update.tenantId}
  AND plan_id = #{update.planId}
  AND id = #{update.revisionId}
  AND version = #{update.expectedVersion}
  AND frozen_at IS NULL

UPDATE sol_construction_plan_revision
SET frozen_at = #{update.frozenAt},
    version = version + 1
WHERE tenant_id = #{update.tenantId}
  AND plan_id = #{update.planId}
  AND id = #{update.revisionId}
  AND version = #{update.expectedVersion}
  AND source_change_id = #{update.sourceChangeId}
  AND frozen_at IS NULL
